/*
 * Terminology search: finds codes and terms across every CodeSystem in this guide.
 * concept-index.json is generated by Jekyll during the IG build (see the file itself);
 * it is copied next to every language's pages, so it is fetched relative to the page.
 */
(function () {
  'use strict';

  var LANG = (document.documentElement.lang || 'en').slice(0, 2);
  var STRINGS = {
    en: { loading: 'Loading the index...', failed: 'Could not load the search index.',
      ready: '{c} concepts in {s} code systems.', none: 'Nothing found.',
      shown: '{n} matches, showing the first {m}.', count: '{n} matches.',
      all: 'All code systems', code: 'Code', term: 'Term', other: 'Other languages', system: 'Code system' },
    ru: { loading: 'Загрузка индекса...', failed: 'Не удалось загрузить поисковый индекс.',
      ready: '{c} концептов в {s} кодовых системах.', none: 'Ничего не найдено.',
      shown: 'Совпадений: {n}, показаны первые {m}.', count: 'Совпадений: {n}.',
      all: 'Все кодовые системы', code: 'Код', term: 'Термин', other: 'Другие языки', system: 'Кодовая система' },
    uz: { loading: 'Indeks yuklanmoqda...', failed: "Qidiruv indeksini yuklab bo'lmadi.",
      ready: '{s} ta kod tizimida {c} ta tushuncha.', none: 'Hech narsa topilmadi.',
      shown: '{n} ta moslik, birinchi {m} tasi ko\'rsatilgan.', count: '{n} ta moslik.',
      all: 'Barcha kod tizimlari', code: 'Kod', term: 'Atama', other: 'Boshqa tillar', system: 'Kod tizimi' }
  };
  var T = STRINGS[LANG] || STRINGS.en;
  var MAX = 200;

  var input = document.getElementById('cs-query');
  var picker = document.getElementById('cs-system');
  var status = document.getElementById('cs-status');
  var results = document.getElementById('cs-results');
  if (!input) return;

  var systems = [];   // {id, t, u, l, k}
  var concepts = [];  // {s, code, display, des: [[lang, value]], hay}

  function fmt(s, o) { return s.replace(/\{(\w)\}/g, function (_, k) { return o[k]; }); }
  function norm(s) {
    return s.toLowerCase().replace(/[‘’ʻʼ`´]/g, "'").replace(/ё/g, 'е');
  }
  function esc(s) {
    return s.replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
  }

  function load() {
    status.textContent = T.loading;
    return fetch('concept-index.json').then(function (r) {
      if (!r.ok) throw new Error(r.status);
      return r.json();
    }).then(function (rows) {
      var current = -1;
      for (var i = 1; i < rows.length; i++) {
        var row = rows[i];
        if (!Array.isArray(row)) { systems.push(row); current = systems.length - 1; continue; }
        var des = [], hay = row[0] + '\u0001' + row[1];
        for (var j = 2; j + 1 < row.length; j += 2) { des.push([row[j], row[j + 1]]); hay += '\u0001' + row[j + 1]; }
        concepts.push({ s: current, code: row[0], display: row[1], des: des, hay: norm(hay) });
      }
      var order = systems.map(function (s, i) { return i; }).sort(function (a, b) {
        return systems[a].t.localeCompare(systems[b].t);
      });
      picker.innerHTML = '<option value="">' + esc(T.all) + '</option>' + order.map(function (i) {
        return '<option value="' + i + '">' + esc(systems[i].t) + '</option>';
      }).join('');
      status.textContent = fmt(T.ready, { c: concepts.length.toLocaleString(), s: systems.length });
    }).catch(function () { status.textContent = T.failed; });
  }

  // Best first: exact code, code prefix, term prefix, word start, anywhere.
  function score(c, q) {
    var code = c.code.toLowerCase();
    if (code === q) return 0;
    if (code.indexOf(q) === 0) return 1;
    var texts = c.hay.split('\u0001').slice(1);
    for (var i = 0; i < texts.length; i++) if (texts[i] === q) return 2;
    for (i = 0; i < texts.length; i++) if (texts[i].indexOf(q) === 0) return 3;
    for (i = 0; i < texts.length; i++) if (new RegExp('(^|[\\s(,.;:/-])' + q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).test(texts[i])) return 4;
    return 5;
  }

  function mark(text, words) {
    var out = esc(text);
    words.forEach(function (w) {
      var re = new RegExp('(' + esc(w).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
      out = out.replace(re, '<mark>$1</mark>');
    });
    return out;
  }

  function term(c) {
    var s = systems[c.s];
    if (s.l === LANG || (!s.l && LANG === 'en')) return c.display;
    for (var i = 0; i < c.des.length; i++) if (c.des[i][0] === LANG) return c.des[i][1];
    return c.display;
  }

  function search() {
    var raw = input.value.trim();
    var params = new URLSearchParams(location.search);
    if (raw) params.set('q', raw); else params.delete('q');
    history.replaceState(null, '', location.pathname + (params.toString() ? '?' + params : ''));
    results.innerHTML = '';
    if (!concepts.length || !raw) return;
    var q = norm(raw), words = q.split(/\s+/), only = picker.value === '' ? -1 : +picker.value;
    var hits = [];
    for (var i = 0; i < concepts.length; i++) {
      var c = concepts[i];
      if (only >= 0 && c.s !== only) continue;
      var ok = true;
      for (var w = 0; w < words.length && ok; w++) ok = c.hay.indexOf(words[w]) >= 0;
      if (ok) hits.push(c);
    }
    hits = hits.map(function (c) { return { c: c, r: score(c, q) }; })
      .sort(function (a, b) { return a.r - b.r || a.c.hay.length - b.c.hay.length; });
    status.textContent = !hits.length ? T.none : hits.length > MAX
      ? fmt(T.shown, { n: hits.length.toLocaleString(), m: MAX }) : fmt(T.count, { n: hits.length });
    if (!hits.length) return;
    var rows = hits.slice(0, MAX).map(function (h) {
      var c = h.c, s = systems[c.s], main = term(c);
      var others = [[s.l || 'en', c.display]].concat(c.des).filter(function (d) { return d[1] && d[1] !== main; });
      var href = 'CodeSystem-' + s.id + '.html#' + encodeURIComponent(s.id + '-' + c.code);
      return '<tr><td><a href="' + href + '"><code>' + mark(c.code, words) + '</code></a></td>' +
        '<td>' + mark(main, words) + '</td>' +
        '<td class="cs-other">' + others.map(function (d) {
          return '<span><b>' + esc(d[0] || '?') + '</b> ' + mark(d[1], words) + '</span>';
        }).join('') + '</td>' +
        '<td><a href="CodeSystem-' + s.id + '.html">' + esc(s.t) + '</a></td></tr>';
    });
    results.innerHTML = '<table class="grid cs-table"><thead><tr><th>' + esc(T.code) + '</th><th>' + esc(T.term) +
      '</th><th>' + esc(T.other) + '</th><th>' + esc(T.system) + '</th></tr></thead><tbody>' + rows.join('') + '</tbody></table>';
  }

  var timer;
  input.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(search, 150); });
  picker.addEventListener('change', search);
  input.value = new URLSearchParams(location.search).get('q') || '';
  load().then(search);
})();
